"""Fifty more non-Devpost opportunities in every interest field.

Adds 50 opportunities for each of the 12 default fields (600 total).
Every entry sets eligible_countries and a 2026 deadline_at.
"""

from __future__ import annotations

import logging
from datetime import UTC, datetime

from sqlalchemy.orm import Session

from app.models.enums import OpportunityType
from scraper.repository import ScrapedOpportunity, upsert_opportunity

logger = logging.getLogger(__name__)

SOURCE_NAME = "field_expand_catalog"

OT = OpportunityType

FIELDS = [
    "ai",
    "biology",
    "business",
    "chemistry",
    "computer-science",
    "economics",
    "engineering",
    "mathematics",
    "physics",
    "research",
    "social-science",
    "writing",
]


def _dt(y: int, m: int, d: int) -> datetime:
    return datetime(y, m, d, 23, 59, 59, tzinfo=UTC)


def _item(
    *,
    external_id: str,
    title: str,
    url: str,
    description: str,
    opportunity_type: OpportunityType,
    field_slugs: list[str],
    eligible_countries: list[str],
    application_url: str | None = None,
    grade_min: int = 9,
    grade_max: int = 12,
    grade_eligibility: str = "High School",
    experience: str | None = None,
    deadline_summary: str = "Check the official site for the current cycle",
    deadline_at: datetime | None = None,
) -> ScrapedOpportunity:
    return ScrapedOpportunity(
        external_id=external_id,
        title=title,
        source_url=url,
        application_url=application_url or url,
        description=description,
        opportunity_type=opportunity_type,
        grade_eligibility=grade_eligibility,
        grade_min=grade_min,
        grade_max=grade_max,
        eligible_countries=eligible_countries,
        experience_requirements=experience,
        deadline_at=deadline_at,
        deadline_summary=deadline_summary,
        field_slugs=field_slugs,
    )


def _type_for(title: str, field: str) -> OpportunityType:
    lower = title.lower()
    if field == "research" or "research" in lower or "summer" in lower:
        if "fair" in lower or "symposium" in lower or "talent" in lower or "prize" in lower:
            return OT.COMPETITION
        return OT.RESEARCH_PROGRAM
    if "olympiad" in lower:
        return OT.OLYMPIAD
    if "scholarship" in lower:
        return OT.SCHOLARSHIP
    return OT.COMPETITION


