FIELD_ROW_GROUPS: list[tuple[str, list[tuple]]] = [
        ("ai", AI_ROWS),
        ("biology", BIOLOGY_ROWS),
        ("business", BUSINESS_ROWS),
        ("chemistry", CHEMISTRY_ROWS),
        ("computer-science", COMPUTER_SCIENCE_ROWS),
        ("economics", ECONOMICS_ROWS),
        ("engineering", ENGINEERING_ROWS),
        ("mathematics", MATHEMATICS_ROWS),
        ("physics", PHYSICS_ROWS),
        ("research", RESEARCH_ROWS),
        ("social-science", SOCIAL_SCIENCE_ROWS),
        ("writing", WRITING_ROWS),
]


def build_field_expand_catalog() -> list[ScrapedOpportunity]:
    items: list[ScrapedOpportunity] = []
    for field, rows in FIELD_ROW_GROUPS:
        if len(rows) != 50:
            raise RuntimeError(f"{field} expected 50 rows, got {len(rows)}")
        for eid, title, url, cc, month, day, desc in rows:
            safe_day = min(day, 28) if month == 2 else day
            items.append(
                _item(
                    external_id=eid,
                    title=title,
                    url=url,
                    description=desc,
                    opportunity_type=_type_for(title, field),
                    field_slugs=[field],
                    eligible_countries=[cc] if cc else [],
                    deadline_at=_dt(2026, month, safe_day),
                    deadline_summary=(
                        "Registration / application window for the 2026 cycle "
                        "(verify official site)"
                    ),
                )
            )

    if len(items) != 600:
        raise RuntimeError(f"field_expand_catalog expected 600 items, got {len(items)}")
    ids = [item.external_id for item in items]
    if len(ids) != len(set(ids)):
        raise RuntimeError("field_expand_catalog has duplicate external_id values")
    for item in items:
        if item.deadline_at is None or item.eligible_countries is None:
            raise RuntimeError(f"{item.external_id} missing deadline or region")
    return items


FIELD_EXPAND_CATALOG = build_field_expand_catalog()


def seed_field_expand_catalog(db: Session) -> dict[str, int]:
    """Upsert field-expand catalog entries."""
    stats = {"listed": 0, "created": 0, "updated": 0, "skipped": 0, "no_deadline": 0}
    items = FIELD_EXPAND_CATALOG
    stats["listed"] = len(items)
    logger.info("Seeding %s — %s opportunit(ies)", SOURCE_NAME, len(items))

    for index, item in enumerate(items, start=1):
        try:
            if item.deadline_at is None:
                stats["no_deadline"] += 1
            _, created = upsert_opportunity(db, item, source_name=SOURCE_NAME)
            if created:
                stats["created"] += 1
            else:
                stats["updated"] += 1
            if index == 1 or index == len(items) or index % 100 == 0:
                logger.info(
                    "[%s/%s] %s %s",
                    index,
                    len(items),
                    "CREATED" if created else "UPDATED",
                    item.title,
                )
        except Exception:
            stats["skipped"] += 1
            logger.exception("Failed to seed %s", item.external_id)
    return stats
